insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$americana$q$, $q$https://www.americana.sp.gov.br/legislacao/decreto_5814_2003.html (Dec. 5.814/2003) ; https://www.americana.sp.gov.br/legislacao/decreto_4722_1998.html (Dec. 4.722/1998) ; https://www.americana.sp.gov.br/legislacao/lei_3621_2002.html (Lei 3.621/2002, inconstitucional)$q$, $q$Atos oficiais de Americana: domínio público (Lei 9.610/1998 art. 8º IV). Geometria das vias: OpenStreetMap (ODbL 1.0, © colaboradores do OSM), casada por nome e trecho. Limite municipal (registro): IBGE (dados públicos).$q$, 49, $q$Dois atos vigentes de circulação: Dec. 5.814/2003 (14 vias do Centro, capacidade de carga > 2 t, seg–sáb 9h–18h, exceto feriados; dezembro 9h–24h, não modelado) e Dec. 4.722/1998 (barragem de solo da Represa Salto Grande, caminhão proibido 24 h). A Lei 3.621/2002 (Centro) foi julgada inconstitucional. O PlanMob (Lei 6.806/2023) prevê decreto de áreas de restrição, ainda não editado. O município não define VUC.$q$);
